#!/usr/bin/env python3
# Сборка украинской «Студии Пикселя»: app/index.html (RU, исходник) -> app/uk/index.html. Claude, 23.10.2026.
# Запуск: python3 app/build_uk.py [--site /uk] [--stickers URL]
# Если в русском файле поменялся текст, а перевода нет — строка останется русской, скрипт выведет предупреждение.
import os, re, sys

HERE = os.path.dirname(os.path.abspath(__file__))
SRC, DST = os.path.join(HERE, 'index.html'), os.path.join(HERE, 'uk', 'index.html')
args = sys.argv[1:]
opt = lambda k, d=None: args[args.index(k) + 1] if k in args else d
SITE = opt('--site', '')
STICKERS = opt('--stickers')

s = open(SRC, encoding='utf-8').read()
missing = []

def rep(a, b):
    global s
    if a not in s:
        missing.append(a[:70])
        return
    s = s.replace(a, b)

# ---- служебное ----
rep('<html lang="ru">', '<html lang="uk">')
rep("  site:'' //", "  site:'%s' //" % SITE)
rep("web:'https://matis.academy/app/'", "web:'https://matis.academy/app/uk/'")
if STICKERS:
    s = re.sub(r"stickers:'[^']*'", "stickers:'%s'" % STICKERS, s, count=1)

