# что осталось кириллицей вне комментариев — для контроля
left = []
for i, line in enumerate(s.split('\n'), 1):
    code = re.sub(r'/\*.*?\*/|<!--.*?-->|//[^\n\'"]*$', '', line)
    if re.search('[ЁёЫыЭэЪъ]', code):  # буквы, которых нет в украинском
        left.append('%d: %s' % (i, code.strip()[:100]))

os.makedirs(os.path.dirname(DST), exist_ok=True)
open(DST, 'w', encoding='utf-8').write(s)
print('built', DST, len(s))
if missing:
    print('NOT FOUND (%d):' % len(missing)); [print('  -', m) for m in missing]
if left:
    print('RUSSIAN LEFT (%d):' % len(left)); [print('  ', l) for l in left]
